def comps(grid,v=None,minv=1):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if v==None or grid[r][c]==v and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
