def dist(A,B):
    a_r=sum(p[0] for p in A)/len(A); a_c=sum(p[1] for p in A)/len(A)
    b_r=sum(q[0] for q in B)/len(B); b_c=sum(q[1] for q in B)/len(B)
    return abs(a_r-b_r)+abs(a_c-b_c)
