G=load(); print(sorted(G))
from collections import deque,Counter
def comps(g,bg=None):
    H,W=len(g),len(g[0])
    if bg is None: bg=g[0][0]
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    rr,cc=q.popleft(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=rr+dr,cc+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                out.append({'col':col,'size':len(cells),'r0':min(q[0] for q in [cells]) and min(p[0] for p in cells),'c0':min(p[1] for p in cells),'cells':set(cells)})
    return out
