from collections import Counter, deque, defaultdict
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; pts=set()
                while q:
                    y,x=q.popleft(); pts.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==col:
                            seen[a][b]=True; q.append((a,b))
                out.append({'col':col,'cells':set(pts)})
    return out
