from collections import Counter,deque
def enclosed_fill(g):
    H,W=len(g),len(g[0]); bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in (0,W-1):
            if g[r][c]==bg and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if g[r][c]==bg and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for da,db in((-1,0),(1,0),(0,-1),(0,1)):
            x,y=r+da,c+db
            if 0<=x<H and 0<=y<W and g[x][y]==bg and not seen[x][y]:
                seen[x][y]=True; q.append((x,y))
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if not seen[r][c]:
                # flood this enclosed pocket, collect non-bg cells
                pq=deque([(r,c)]); mask=set()
                while pq:
                    a,b=pq.popleft()
                    if (a,b) in mask: continue
                    mask.add((a,b))
                    if g[a][b]!=bg: out[a][b]=bg
                    for da,db in((-1,0),(1,0),(0,-1),(0,1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and (x,y) not in mask: pq.append((x,y))
    return out
