def comps8(gi,bg):
    H,W=len(gi),len(gi[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c]!=bg and not seen[r][c]:
                col=gi[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x][y] and gi[x][y]==col:
                                seen[x][y]=True; q.append((x,y))
                out.append({'col':col,'cells':set(cells)})
    return out
